package com.mycompany.rentalmanagement.util;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.SecureRandom;import java.util.HexFormat;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;
public final class PasswordUtil {private static final int ITERATIONS=120000;private static final int KEY_BITS=256;private PasswordUtil(){} public static String hash(String value){byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);return encode(value,salt,ITERATIONS);} private static String encode(String value,byte[] salt,int iterations){try{PBEKeySpec spec=new PBEKeySpec(value.toCharArray(),salt,iterations,KEY_BITS);byte[] key=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return "PBKDF2$"+iterations+"$"+HexFormat.of().formatHex(salt)+"$"+HexFormat.of().formatHex(key);}catch(Exception e){throw new IllegalStateException("Unable to hash password",e);}} public static boolean verify(String value,String stored){try{String[] parts=stored.split("\\$");if(parts.length!=4||!"PBKDF2".equals(parts[0]))return false;int iterations=Integer.parseInt(parts[1]);byte[] salt=HexFormat.of().parseHex(parts[2]);String actual=encode(value,salt,iterations).split("\\$")[3];return MessageDigest.isEqual(actual.getBytes(StandardCharsets.UTF_8),parts[3].getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}}
